<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class MemberController extends Controller{
public function index(Request $request){$user=$request->user();abort_unless(in_array($user->status,['verified','active'],true),403,'Membership verification required.');$year=$user->role==='super_admin'?$request->integer('year'):$user->graduating_year;return User::query()->select(['id','name','graduating_year','occupation','company','location','photo_url','privacy'])->whereIn('status',['verified','active'])->when($year,fn($q,$v)=>$q->where('graduating_year',$v))->when($request->location,fn($q,$v)=>$q->where('location','like',"%$v%"))->when($request->profession,fn($q,$v)=>$q->where('occupation','like',"%$v%"))->orderBy('name')->paginate(24);}
public function profile(Request $request){return $request->user()->load(['set','activities']);}
public function updateProfile(Request $request){$data=$request->validate(['name'=>'sometimes|string|max:120','phone'=>'nullable|string|max:30','occupation'=>'nullable|string|max:120','company'=>'nullable|string|max:120','location'=>'nullable|string|max:120','bio'=>'nullable|string|max:2000','privacy'=>'nullable|array','photo'=>'sometimes|image|mimes:jpeg,jpg,png,webp|max:5120']);$user=$request->user();if($request->hasFile('photo')){if($user->photo_url&&str_contains($user->photo_url,'/storage/'))Storage::disk('public')->delete(str($user->photo_url)->after('/storage/')->toString());$path=$request->file('photo')->store('profiles','public');$data['photo_url']=Storage::disk('public')->url($path);}unset($data['photo']);$user->update($data);return response()->json(['message'=>'Profile updated.','user'=>$user->fresh()]);}
}
